import fs from "node:fs";
import path from "node:path";
import { spawn } from "node:child_process";
import { fileURLToPath, pathToFileURL } from "node:url";
const area = path.dirname(fileURLToPath(import.meta.url));
const source = path.join(area, "source");
const { _electron: electron } = await import(pathToFileURL(path.join(source, "node_modules/playwright/index.mjs")));
const launch = electron.launch.bind(electron);
electron.launch = async (...args) => {
 const app = await launch(...args);
 const child = app.process();
 const prefix = "__release_quit_observation__";
 const output = fs.createWriteStream(path.join(area, "coding-quit-r4-main.log"));
 let timer;
 child.stdout.on("data", chunk => {
  output.write(chunk);
  if (chunk.toString().includes(prefix) && chunk.toString().includes('"event":"before-quit"') && !timer) {
   timer = setTimeout(() => {
    if (child.exitCode !== null || child.signalCode !== null) return;
    const sample = spawn("/usr/bin/sample", [String(child.pid), "1", "1", "-mayDie", "-file", path.join(area,"coding-quit-r4-sample.txt")], {stdio:["ignore", "pipe", "pipe"], timeout:30000});
    sample.stdout.on("data", chunk => output.write(chunk));
    sample.stderr.on("data", chunk => output.write(chunk));
   }, 4000);
  }
 });
 child.stderr.on("data", chunk => output.write(chunk));
 child.once("exit", (code, signal) => { clearTimeout(timer); output.end(JSON.stringify({event:"actual-child-exit",code,signal})+"\n"); });
 await app.evaluate(({app,BrowserWindow}, prefix) => {
  for (const event of ["before-quit","will-quit","quit"])
   app.prependListener(event, () => process.stdout.write(prefix+JSON.stringify({event,at:new Date().toISOString(),windows:BrowserWindow.getAllWindows().length,resources:process.getActiveResourcesInfo()})+"\n"));
 }, prefix);
 return app;
};
process.argv = [process.execPath, path.join(source,"scripts/electron/code-artifact-workbench-fixture-smoke.mjs"), "--scenario","gui-coding-input","--prefix","release-v11660-coding-r4","--timeout-ms","180000"];
await import(pathToFileURL(process.argv[1]));
